const body = $input.first().json.body || $input.first().json;
const transcript = body.transcript || body.summary?.transcript || body.meeting?.transcript || '';
const title = body.title || body.meeting?.title || 'Untitled meeting';
const recording_url = body.share_url || body.recording_url || body.meeting?.url || '';
const started_at = body.start_time || body.meeting?.start_time || new Date().toISOString();
const attendees = (body.attendees || body.meeting?.attendees || []).map(a => a.name || a.display_name || a.email).filter(Boolean);
if (!transcript) throw new Error('No transcript in payload');
return [{ json: { title, transcript, recording_url, started_at, attendees } }];

values.content:
=You extract action items from meeting transcripts. Return ONLY valid JSON.

Meeting: {{ $json.title }}
Attendees: {{ $json.attendees.join(', ') }}
Started: {{ $json.started_at }}

Transcript:
{{ $json.transcript }}

Return:
{
  "recap": "3-4 sentence summary of what was decided",
  "tasks": [
    {
      "title": "verb-first task name, max 80 chars",
      "owner_name": "first name from attendee list, or 'unassigned'",
      "due": "YYYY-MM-DD or empty if not stated",
      "priority": "urgent|high|normal|low",
      "context": "one sentence why this matters"
    }
  ],
  "open_questions": ["questions raised but not answered"]
}

Rules:
- Only items that have a clear owner or implied owner. No vague 'team should consider'
- Verbs first: 'Send', 'Draft', 'Review', 'Schedule'
- If a date like 'by Friday' was said, resolve it relative to the meeting date

parameters.jsCode:
const NAME_TO_ID = {
  'waseem': 12345001,
  'sara': 12345002,
  'omar': 12345003,
  'ayesha': 12345004,
  'naeem': 12345005
};
const raw = $input.first().json.content?.[0]?.text || $input.first().json.text || '';
const match = raw.match(/\{[\s\S]*\}/);
if (!match) throw new Error('No JSON');
const parsed = JSON.parse(match[0]);
const meta = $('Normalise payload').first().json;
const tasks = (parsed.tasks || []).map(t => ({
  ...t,
  clickup_user_id: NAME_TO_ID[(t.owner_name || '').toLowerCase().trim()] || null,
  meeting_title: meta.title,
  recording_url: meta.recording_url
}));
return [{ json: { recap: parsed.recap, open_questions: parsed.open_questions || [], tasks, meeting_title: meta.title, recording_url: meta.recording_url } }];

